import { readFileSync } from 'node:fs';
import path from 'node:path';
import ts from 'typescript';
import { describe, expect, it } from 'vitest';

import { findRepoRoot } from './repoRoot';

// devcontainer-lock.json is regenerated by the Dev Containers tooling, and
// hand edits to devcontainer.json left it describing other features (#34,
// #35, ae23238, afabb95). The Dev Containers CLI looks a feature's lock
// entry up by its exact id, so the two files must list the same ids.
const root = findRepoRoot(import.meta.dirname);

function readJsonc(file: string) {
  const { config, error } = ts.parseConfigFileTextToJson(
    file,
    readFileSync(path.join(root, file), 'utf8'),
  );
  if (error) throw new Error(`${file}: ${String(error.messageText)}`);
  return config as { features?: Record<string, { version?: string }> };
}

const configured = readJsonc('.devcontainer/devcontainer.json').features ?? {};
const locked = readJsonc('.devcontainer/devcontainer-lock.json').features ?? {};

describe('devcontainer-lock.json matches devcontainer.json', () => {
  it('locks exactly the configured features', () => {
    expect(Object.keys(locked).sort()).toEqual(Object.keys(configured).sort());
  });

  it('locks each feature pinned to a version at that version', () => {
    const pinned = Object.keys(configured).flatMap((id) => {
      const tag = id.match(/:(\d+\.\d+\.\d+)$/)?.[1];
      return tag ? [[id, tag] as const] : [];
    });

    expect(pinned.length).toBeGreaterThan(0);
    expect(
      Object.fromEntries(pinned.map(([id]) => [id, locked[id]?.version])),
    ).toEqual(Object.fromEntries(pinned));
  });
});
